fn fields(line: &str) -> Vec<String> {
    line.split(',')
        .map(|f| f.trim().to_string())
        .collect()
}

fn main() {
    let input =
        ["7,ok,12.5", "8,late,40.1"];
    for line in input {
        let f = fields(line);
        println!("{} {}", f[0], f[1]);
    }
}

