fn main() {
    let input =
        ["7,ok,12.5", "8,late,40.1"];
    let mut buf = String::new();
    let mut batch = Vec::new();
    for line in input {
        buf.clear();
        buf.push_str(line);
        let id = buf.split(',').next();
        batch.push(id.unwrap());
    }
    println!("{}", batch.len());
}

use std::thread;

fn main() {
    let buf = String::from(
        "7,ok,12.5\n8,late,40.1",
    );
    let batch: Vec<&str> =
        buf.lines().collect();
    let writer = thread::spawn(move || {
        let n = batch.len();
        println!("{n} rows");
    });
    writer.join().unwrap();
}
